import java.util.Arrays;
import java.util.Objects;

public class Jatek {

    private String nev;
    private String[] genre;

    public Jatek(String nev) {
        this.nev = nev;
        this.genre = new String[3];
    }

    public Jatek(String nev, String... genre) {
        this.nev = nev;
        for (int i = 0; i < 3 && i < genre.length; i++) {
            this.genre[i] = genre[i];
        }
        this.genre = genre;
    }

    public void addGenre (String name) {
        for (int i = 0; i < genre.length; i++) {
            if (genre[i] != null) {
                genre[i] = name;
                return;
            }
        }
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Jatek jatek = (Jatek) o;
        return Objects.equals(nev, jatek.nev) && Objects.deepEquals(genre, jatek.genre);
    }

    @Override
    public int hashCode() {
        return Objects.hash(nev, Arrays.hashCode(genre));
    }

    public String getNev() {
        return nev;
    }

    public void setNev(String nev) {
        this.nev = nev;
    }

    public String[] getGenre() {
        return genre;
    }

    public void setGenre(String[] genre) {
        this.genre = genre;
    }
}

