        this.melyikJatekot = melyiket;
    }

    public Jatek getMelyikJatekot() {
        return melyikJatekot;
    }
}


import java.util.Map;

public class Jatekos {

    private String nev;
    private Jatek kedvenc;
    private Map<Jatek, Integer> eddigJatszott;


    public Jatekos(String nev) {
        this.nev = nev;
        this.kedvenc = null;
    }

    public void jatszik(Jatek mit, int mennyit) throws NemSzeretiException {

        if (kedvenc != null) {
            boolean vanKozos = false; //megnezzuk van-e kozos
            for (String egyKedvencGenre : kedvenc.getGenre()) {
                for (String genre : mit.getGenre()) {
                    if (genre.equals(egyKedvencGenre)) {
                        vanKozos = true;
                        break;
                    }
                }
            }
            if (vanKozos) { //ha van kozos, jatszik
                hajlando(mit, mennyit);
            } else { //ha nincs, nem.
                throw new NemSzeretiException(mit);
            }

        } else { //ha null a kedvenc, jatszik
            hajlando(mit, mennyit);
        }

        int legtobbIdo = 0;
        for (Map.Entry<Jatek, Integer> entry : eddigJatszott.entrySet()) {
            if (entry.getValue() > legtobbIdo) {
                legtobbIdo = entry.getValue();
            }
        }

        for (Map.Entry<Jatek, Integer> entry : eddigJatszott.entrySet()) {
            if (entry.getValue() == legtobbIdo) {
                kedvenc = entry.getKey();
            }
        }


    }

    private void hajlando(Jatek jatek, int mennyit) {
     eddigJatszott.put(jatek, eddigJatszott.getOrDefault(jatek, 0) + mennyit);
    }

    public Map<Jatek, Integer> getEddigJatszott() {
        return eddigJatszott;
    }

