import java.util.ArrayList;
import java.util.List;

public class Csapat {

    private final Jatek celJatek;
    private final int maxLetszam;
    private List<Jatekos> jatekosok;

    public Csapat(Jatek celJatek, int maxLetszam) {
        this.celJatek = celJatek;
        this.maxLetszam = maxLetszam;
        this.jatekosok = new ArrayList<>();
    }

    public void jatekostHozzaad(Jatekos jatekos) {
        if (!jatekos.getKedvenc().equals(celJatek)) {
            throw new IllegalArgumentException("Ezt a jatekost nem lehet a csapathoz adni!");
        } else
        if (jatekosok.size() >= maxLetszam) {
            throw new IndexOutOfBoundsException("Ide mar nem fer jatekos!");
        } else {
            jatekosok.add(jatekos);
        }
    }

    public Jatek getCelJatek() {
        return celJatek;
    }
}


import java.util.List;
import java.util.Map;

public class Szervezo {

    private List<Jatekos> jatekosok;
    private List<Csapat> csapatok;


    public void addJatekos(Jatekos j) {
        jatekosok.add(j);
    }

    public void addCsapat(Csapat c) {
        csapatok.add(c);
    }

    public void gyakoroltat(Map<Jatek, Integer> mibolMennyit) {


        for (Jatekos jatekos : jatekosok) {
            boolean jatszotte = false;
            for (Map.Entry<Jatek, Integer> entry : mibolMennyit.entrySet()) {
                try {
                    jatekos.jatszik(entry.getKey(), entry.getValue());
                    jatszotte = true; //ha nem dob kivetelt, a jatekos sikeresen jatszott
                } catch (NemSzeretiException e) {
                    throw new RuntimeException(e);
                }
            }
            if (jatszotte == false) {
                throw new SecurityException("Az egyik jatekos tul valogatos.");
            }
        }
    }

    public void beoszt() throws Exception {
        for (Jatekos jatekos : jatekosok) {
            boolean felvettek = false;
            int kompatibilisCsapatok = 0;
            int beteltCsapatok = 0;

            for (Csapat csapat : csapatok) {
                if (csapat.getCelJatek().equals(jatekos.getKedvenc())) {
                    kompatibilisCsapatok++;
                    try {
                        csapat.jatekostHozzaad(jatekos);
                        felvettek = true;
                        break;
                    } catch (IndexOutOfBoundsException e) {
                        // A csapat betelt
                        beteltCsapatok++;
                    }

                }

            }
            if (!felvettek) {
                if (kompatibilisCsapatok == 0) {
                    throw new Exception("Az egyik jatekosnak nem sikerult megfelelo csapatot talalni.");
                }else if (beteltCsapatok == kompatibilisCsapatok) {
                    throw new Exception("Az egyik jatekosnak " + kompatibilisCsapatok + " csapatot talalt, de mind tele van.");
                }
            }
        }
    }
}



